SET NAMES utf8mb4;

DROP TABLE IF EXISTS `community_device`;
CREATE TABLE `community_device` (
  `device_id` bigint NOT NULL COMMENT '设备ID',
  `community_id` bigint DEFAULT NULL COMMENT '小区ID',
  `building_id` bigint DEFAULT NULL COMMENT '楼栋ID',
  `unit_id` bigint DEFAULT NULL COMMENT '单元ID',
  `device_name` varchar(100) DEFAULT NULL COMMENT '设备名称',
  `device_code` varchar(64) DEFAULT NULL COMMENT '设备编号',
  `device_type` varchar(32) DEFAULT NULL COMMENT '设备类型（门禁 电梯 摄像头 消防 照明 其他）',
  `device_location` varchar(255) DEFAULT NULL COMMENT '设备位置',
  `device_status` char(1) DEFAULT '0' COMMENT '设备状态（0正常 1故障 2维修中 3停用）',
  `online_status` char(1) DEFAULT '0' COMMENT '在线状态（0在线 1离线）',
  `manufacturer` varchar(100) DEFAULT NULL COMMENT '生产厂商',
  `install_date` date DEFAULT NULL COMMENT '安装日期',
  `last_maintain_time` datetime DEFAULT NULL COMMENT '上次维护时间',
  `next_maintain_time` datetime DEFAULT NULL COMMENT '下次维护时间',
  `alarm_status` char(1) DEFAULT '0' COMMENT '告警状态（0无告警 1有告警）',
  `alarm_content` varchar(255) DEFAULT NULL COMMENT '告警内容',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建者',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新者',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(1024) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`device_id`),
  KEY `idx_device_community_id` (`community_id`),
  KEY `idx_device_building_id` (`building_id`),
  KEY `idx_device_unit_id` (`unit_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='设备信息表';

DROP TEMPORARY TABLE IF EXISTS `tmp_device_ref`;
CREATE TEMPORARY TABLE `tmp_device_ref` AS
SELECT (@rownum := @rownum + 1) AS rn, t.community_id, t.building_id, t.unit_id, t.building_name, t.unit_name
FROM (
  SELECT DISTINCT c.community_id, b.building_id, u.unit_id, b.building_name, u.unit_name
  FROM `community` c
  LEFT JOIN `building` b ON b.community_id = c.community_id
  LEFT JOIN `unit` u ON u.building_id = b.building_id
  ORDER BY c.community_id, b.building_id, u.unit_id
  LIMIT 4
) t, (SELECT @rownum := 0) r;


